// Utilitários Globais de Formatação e Design System (I20)
function getProgressColor(pct) {
  const p = Number(pct) || 0;
  if (p >= 100) return 'var(--color-completed, #34c759)';
  if (p >= 50) return 'var(--accent, #2997ff)';
  if (p >= 25) return 'var(--color-est, #f59e0b)';
  return 'var(--color-text-secondary, #86868b)';
}

function formatCurrencyBRL(val) {
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(val) || 0);
}

function formatDateBR(dateVal) {
  if (!dateVal) return '-';
  const d = new Date(dateVal);
  return isNaN(d.getTime()) ? String(dateVal) : d.toLocaleDateString('pt-BR');
}

function formatAreaM2(val) {
  return `${Number(val || 0).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 2 })} m²`;
}

function formatVolumeM3(val) {
  return `${Number(val || 0).toLocaleString('pt-BR', { minimumFractionDigits: 1, maximumFractionDigits: 2 })} m³`;
}

if (typeof window !== 'undefined') {
  window.getProgressColor = getProgressColor;
  window.formatCurrencyBRL = formatCurrencyBRL;
  window.formatDateBR = formatDateBR;
  window.formatAreaM2 = formatAreaM2;
  window.formatVolumeM3 = formatVolumeM3;
}
if (typeof global !== 'undefined') {
  global.getProgressColor = getProgressColor;
  global.formatCurrencyBRL = formatCurrencyBRL;
  global.formatDateBR = formatDateBR;
  global.formatAreaM2 = formatAreaM2;
  global.formatVolumeM3 = formatVolumeM3;
}

