        environmentId: environments[0] ? environments[0].id : null,
        content: {
          environments: environments.map(e => ({ id: e.id, name: e.name, area: e.areaM2 || e.area || '-' })),
          highlightEnv: environments[0] ? environments[0].name : 'Ambiente Principal'
        },
